-- #116 원장 계정과 이벤트 유형 (ADR-0107 결정 2 #73 1·2·3·7·10·11·15·16항, 결정 3 '배포 DB 초기화(#116)',
-- 결정 5 '#116 시작 지급의 기록과 옛 가입 지급'; ADR-0109). The ledger becomes a record of moves
-- between ledger accounts — a person's own, the operating treasury, each market's collateral and
-- each market's 마켓메이커 자금 — and the deployed database is wiped once more, accounts included:
-- testers sign up again, and the seed that runs after every migrate makes the two admins, the 14
-- draft markets and the 운영 마켓메이커 account again. Generated by `drizzle-kit generate`, then
-- hand-edited where marked: this header, the wipe, the primary-key swap of `balances` and the tail;
-- the two `(account, id)` indexes were added to the schema after and written here as generated.
-- The snapshot matches the schema (a re-run of `generate` reports no changes).
--
-- 1. The wipe comes first, as in 0017 and 0048: every table in schema `public` is truncated,
--    RESTART IDENTITY CASCADE; `drizzle.__drizzle_migrations` is another schema and survives. The
--    statement is WIPE_PUBLIC_TABLES_SQL (src/wipe.ts); wipe.test.ts keeps the copies identical.
-- 2. With every table empty: `ledger_entry_type` is rebuilt by drizzle-kit's own enum rebuild
--    (column to text, DROP TYPE, CREATE TYPE, cast back) with the types of LEDGER_ENTRY_TYPES —
--    ADMIN_ADJUST (#73 7항), TRADE_BUY, TRADE_SELL and FEE (15항) go —; `ledger_entries` loses
--    `user_id` and `balance_after_coin` and gains its two accounts, their totals after the event,
--    its market and its key, NOT NULL where the table could not have taken it before; `balances`
--    is keyed by its ledger account (`balances_pkey` dropped by hand: drizzle-kit cannot name it),
--    `user_id` kept as a copy for a person's, and gains `ledger_coin`, the account's total as its
--    ledger says; `markets.taker_fee_bps`·`settlement_fee_bps` and their CHECK go (fees are a code
--    0, 15항).
--
-- Redis and the media bucket are not touched (docs/RESET.md, as for 0048).
DO $$
DECLARE
  table_list text;
BEGIN
  SELECT string_agg(format('%I.%I', schemaname, tablename), ', ' ORDER BY tablename)
    INTO table_list
    FROM pg_tables
   WHERE schemaname = 'public';
  IF table_list IS NOT NULL THEN
    EXECUTE 'TRUNCATE TABLE ' || table_list || ' RESTART IDENTITY CASCADE';
  END IF;
END
$$;--> statement-breakpoint
CREATE TYPE "public"."ledger_account_kind" AS ENUM('user', 'treasury', 'market_collateral', 'market_maker_funds');--> statement-breakpoint
CREATE TABLE "ledger_accounts" (
	"id" bigserial PRIMARY KEY NOT NULL,
	"kind" "ledger_account_kind" NOT NULL,
	"owner_id" text,
	"market_id" uuid,
	"created_at" timestamp (3) with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "ledger_accounts_shape_check" CHECK (("ledger_accounts"."kind" = 'user' AND "ledger_accounts"."owner_id" IS NOT NULL AND "ledger_accounts"."market_id" IS NULL)
        OR ("ledger_accounts"."kind" = 'treasury' AND "ledger_accounts"."owner_id" IS NULL AND "ledger_accounts"."market_id" IS NULL)
        OR ("ledger_accounts"."kind" = 'market_collateral' AND "ledger_accounts"."owner_id" IS NULL AND "ledger_accounts"."market_id" IS NOT NULL)
        OR ("ledger_accounts"."kind" = 'market_maker_funds' AND "ledger_accounts"."owner_id" IS NOT NULL
