-- Hand-edited: which ledger accounts each type moves Coin between (ADR-0107 결정 2 #73 1·3·10항):
-- the SQL copy of LEDGER_ENTRY_RULES' pairs (@buddha/shared ledger.ts), '-' standing for a mint's
-- from-side or a burn's to-side. Pairs, not a product of the sides' kinds: a correction takes no
-- user's Coin and a pair's burn returns to the bot's funds only. ledger.test.ts (@buddha/db) keeps
-- the two equal for every type and pair; a type added later replaces this function with its rows.
-- LANGUAGE sql without BEGIN ATOMIC, like every function here: no dependency is recorded.
CREATE FUNCTION ledger_entry_direction_allowed(entry_type text, from_kind text, to_kind text)
RETURNS boolean
LANGUAGE sql IMMUTABLE AS $$
  SELECT (entry_type, coalesce(from_kind, '-'), coalesce(to_kind, '-')) IN (VALUES
    ('START_GRANT', '-', 'user'),
    ('TREASURY_MINT', '-', 'treasury'),
    ('BOT_ALLOCATION', 'treasury', 'market_maker_funds'),
    ('BOT_RECALL', 'market_maker_funds', 'treasury'),
    ('PAIR_MINT_COLLATERAL', 'user', 'market_collateral'),
    ('PAIR_MINT_COLLATERAL', 'market_maker_funds', 'market_collateral'),
    ('PAIR_BURN_RETURN', 'market_collateral', 'market_maker_funds'),
    ('TRADE_FILL', 'user', 'user'),
    ('TRADE_FILL', 'user', 'market_maker_funds'),
    ('TRADE_FILL', 'market_maker_funds', 'user'),
    ('SETTLEMENT_PAYOUT', 'market_collateral', 'user'),
    ('SETTLEMENT_PAYOUT', 'market_collateral', 'market_maker_funds'),
    ('CLOSURE_FORFEIT', 'user', '-'),
    ('RECONCILIATION_CORRECTION', 'treasury', 'user'),
    ('RECONCILIATION_CORRECTION', 'treasury', 'market_collateral'),
    ('RECONCILIATION_CORRECTION', 'market_collateral', 'treasury'),
    ('RECONCILIATION_CORRECTION', 'treasury', 'market_maker_funds'),
    ('RECONCILIATION_CORRECTION', 'market_maker_funds', 'treasury'),
    ('DEPOSIT', '-', 'user'),
    ('BONUS', '-', 'user'),
    ('PAYMENT_CANCEL', 'user', '-'),
    ('PAYMENT_CANCEL_REVERSAL', '-', 'user')
  );
$$;--> statement-breakpoint
-- Hand-edited: a ledger account's total after its latest event, or 0 before its first — what its
-- `balances` row must carry as `ledger_coin` (and hold, available + locked, but for a gap an
-- owner-level write left: see `balances_keep_ledger_gap`). The latest by id, one probe of each
-- side's (account, id) index: for one account the id is commit order, which `ledger_entries_check`
-- holds (the balance rows locked, an id past the account's latest and handed out by the sequence).
-- Never by `created_at`, which follows the database's wall clock: a clock stepped back (NTP, a
-- resumed VM) would make an older event the latest and refuse every write on the account until the
-- clock caught up. `created_at` orders the listing only. The table is named with its schema: a
-- session's pg_temp is searched first for a relation, and PUBLIC may create temporary tables, so a
-- bare name would let buddha_app answer every guard below with a table of its own (0034).
CREATE FUNCTION ledger_account_last_after(of_account bigint) RETURNS bigint
LANGUAGE sql STABLE AS $$
  SELECT coalesce((
    SELECT latest.after FROM (
      (SELECT e.id, e.from_balance_after_coin AS after FROM public.ledger_entries e
        WHERE e.from_account_id = of_account ORDER BY e.id DESC LIMIT 1)
      UNION ALL
      (SELECT e.id, e.to_balance_after_coin AS after FROM public.ledger_entries e
        WHERE e.to_account_id = of_account ORDER BY e.id DESC LIMIT 1)
    ) latest
    ORDER BY latest.id DESC
    LIMIT 1
  ), 0);
$$;--> statement-breakpoint
-- Hand-edited: an event is one its type allows, whoever writes (`recordLedgerEntry` checks the
-- same first): its (from, to) pair; its market — a market's account (the collateral, a 마켓메이커
-- 자금) names the event's own market, and with none on either side only a fill between two people
-- names one; and each side's total after the event, which continues that account's chain (its
-- last total minus or plus the amount), so an account's latest event always says its ledger
-- total.
-- The chain is read with both accounts' balance rows locked (FOR UPDATE, ascending), held to the
-- commit: `recordLedgerEntry` already holds them, and a writer that does not waits here for any
-- other writer of those accounts and then reads its event, so no two events chain from one total
-- and none commits without its balance change unseen behind another's. And the id is past each
-- account's latest and no greater than the sequence has handed out: buddha_app may name an id, and
-- one below the latest would hide its event from the COMMIT check, one far ahead would make every
-- later event of the account look older than it. An id drawn before a wait, below an event that
-- committed meanwhile, is refused too. The search path is fixed with pg_temp last, as for every
-- function below that reads a table (see `ledger_account_last_after`).
CREATE FUNCTION ledger_entries_check() RETURNS trigger
LANGUAGE plpgsql SET search_path = pg_catalog, public, pg_temp AS $$
DECLARE
  from_kind text;
  from_market uuid;
  to_kind text;
  to_market uuid;
  latest_id bigint;
BEGIN
  IF NEW.from_account_id IS NOT NULL THEN
    SELECT a.kind::text, a.market_id INTO from_kind, from_market
      FROM ledger_accounts a WHERE a.id = NEW.from_account_id;
  END IF;
  IF NEW.to_account_id IS NOT NULL THEN
    SELECT a.kind::text, a.market_id INTO to_kind, to_market
      FROM ledger_accounts a WHERE a.id = NEW.to_account_id;
  END IF;
  IF NOT ledger_entry_direction_allowed(NEW.type::text, from_kind, to_kind) THEN
    RAISE EXCEPTION 'a % event does not move Coin from % to %', NEW.type,
      coalesce(from_kind, 'a mint'), coalesce(to_kind, 'a burn')
      USING ERRCODE = 'integrity_constraint_violation', CONSTRAINT = TG_NAME;
  END IF;
  IF (from_market IS NOT NULL AND from_market IS DISTINCT FROM NEW.market_id)
     OR (to_market IS NOT NULL AND to_market IS DISTINCT FROM NEW.market_id)
     OR (from_market IS NULL AND to_market IS NULL
         AND (NEW.market_id IS NOT NULL) <> (NEW.type::text = 'TRADE_FILL')) THEN
    RAISE EXCEPTION 'a % event names the market of its accounts, and only then a market', NEW.type
      USING ERRCODE = 'integrity_constraint_violation', CONSTRAINT = TG_NAME;
  END IF;
  PERFORM 1 FROM balances b
   WHERE b.account_id IN (NEW.from_account_id, NEW.to_account_id)
   ORDER BY b.account_id
     FOR UPDATE;
  SELECT max(latest.id) INTO latest_id FROM (
    (SELECT e.id FROM ledger_entries e WHERE e.from_account_id = NEW.from_account_id
      ORDER BY e.id DESC LIMIT 1)
    UNION ALL
    (SELECT e.id FROM ledger_entries e WHERE e.to_account_id = NEW.from_account_id
      ORDER BY e.id DESC LIMIT 1)
    UNION ALL
    (SELECT e.id FROM ledger_entries e WHERE e.from_account_id = NEW.to_account_id
      ORDER BY e.id DESC LIMIT 1)
    UNION ALL
    (SELECT e.id FROM ledger_entries e WHERE e.to_account_id = NEW.to_account_id
      ORDER BY e.id DESC LIMIT 1)
  ) latest;
  IF NEW.id <= coalesce(latest_id, 0)
     OR NEW.id > coalesce(pg_sequence_last_value('public.ledger_entries_id_seq'::regclass), 0) THEN
    RAISE EXCEPTION 'a % event takes an id after its accounts'' latest events, from the sequence',
      NEW.type
      USING ERRCODE = 'integrity_constraint_violation', CONSTRAINT = TG_NAME;
  END IF;
  IF (NEW.from_account_id IS NOT NULL AND NEW.from_balance_after_coin
        IS DISTINCT FROM ledger_account_last_after(NEW.from_account_id) - NEW.amount_coin)
     OR (NEW.to_account_id IS NOT NULL AND NEW.to_balance_after_coin
        IS DISTINCT FROM ledger_account_last_after(NEW.to_account_id) + NEW.amount_coin) THEN
    RAISE EXCEPTION 'a % event does not continue its accounts'' totals', NEW.type
      USING ERRCODE = 'integrity_constraint_violation', CONSTRAINT = TG_NAME;
  END IF;
  RETURN NEW;
END;
$$;--> statement-breakpoint
CREATE TRIGGER ledger_entries_check
  BEFORE INSERT ON "ledger_entries"
  FOR EACH ROW EXECUTE FUNCTION ledger_entries_check();--> statement-breakpoint
-- Hand-edited: an event is a permanent fact (PLAN 5.6), whoever writes — buddha_app lost UPDATE and
-- DELETE in 0001; the migration role and a script lose them here, as 0055 did for judgements. A
-- mistake is answered by another event (대사 정정, #93), never by an edit. TRUNCATE fires no row
-- trigger: the wipe still empties the table.
CREATE FUNCTION ledger_entries_keep_record() RETURNS trigger
LANGUAGE plpgsql AS $$
BEGIN
  RAISE EXCEPTION 'ledger entry % is a permanent record and takes no %', OLD.id, TG_OP
    USING ERRCODE = 'integrity_constraint_violation', CONSTRAINT = TG_NAME;
END;
$$;--> statement-breakpoint
CREATE TRIGGER ledger_entries_keep_record
  BEFORE UPDATE OR DELETE ON "ledger_entries"
  FOR EACH ROW EXECUTE FUNCTION ledger_entries_keep_record();--> statement-breakpoint
-- Hand-edited: a ledger account is made once and never changes or goes (its events name it), and a
-- `user` one belongs to a person (`is_human_account`, 0059: admins and closed accounts too) while a
-- 마켓메이커 자금 belongs to the operating account — never a person's (ADR-0107 결정 2 #73 11항).
-- The shape CHECK holds the rest. Whoever writes; TRUNCATE fires no row trigger. `is_human_account`
-- reads "user" by this function's fixed search path.
CREATE FUNCTION ledger_accounts_check() RETURNS trigger
LANGUAGE plpgsql SET search_path = pg_catalog, public, pg_temp AS $$
BEGIN
  IF TG_OP <> 'INSERT' THEN
    RAISE EXCEPTION 'ledger account % is a permanent record and takes no %', OLD.id, TG_OP
      USING ERRCODE = 'integrity_constraint_violation', CONSTRAINT = TG_NAME;
  END IF;
  IF NEW.kind = 'user' AND NOT is_human_account(NEW.owner_id) THEN
    RAISE EXCEPTION 'account % is not a person''s: it has no user ledger account', NEW.owner_id
      USING ERRCODE = 'integrity_constraint_violation', CONSTRAINT = TG_NAME;
  END IF;
  IF NEW.kind = 'market_maker_funds' AND is_human_account(NEW.owner_id) THEN
    RAISE EXCEPTION 'account % is a person''s: it holds no 마켓메이커 자금', NEW.owner_id
      USING ERRCODE = 'integrity_constraint_violation', CONSTRAINT = TG_NAME;
  END IF;
  RETURN NEW;
END;
$$;--> statement-breakpoint
CREATE TRIGGER ledger_accounts_check
  BEFORE INSERT OR UPDATE OR DELETE ON "ledger_accounts"
  FOR EACH ROW EXECUTE FUNCTION ledger_accounts_check();--> statement-breakpoint
REVOKE UPDATE, DELETE ON TABLE "ledger_accounts" FROM buddha_app;--> statement-breakpoint
-- Hand-edited: every ledger account is born with its `balances` row at 0, the owner copied for a
-- person's — the only way a row comes to be: buddha_app loses INSERT and DELETE of `balances` below
-- and may UPDATE the amounts (the two buckets and the ledger's total) and `updated_at` only, so the
-- owner's copy never drifts. SECURITY DEFINER, as the table's owner, with the search path fixed
-- and pg_temp last (0034), and nobody may EXECUTE it (0044's REVOKE): Postgres checks that only at
-- CREATE TRIGGER, so this trigger keeps firing, while buddha_app cannot attach the function to a
-- temporary table of its own and open a row past the REVOKE below.
CREATE FUNCTION ledger_accounts_open_balance() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog, public, pg_temp AS $$
BEGIN
  INSERT INTO public.balances (account_id, user_id)
  VALUES (NEW.id, CASE WHEN NEW.kind = 'user' THEN NEW.owner_id END);
  RETURN NULL;
END;
$$;--> statement-breakpoint
CREATE TRIGGER ledger_accounts_open_balance
  AFTER INSERT ON "ledger_accounts"
  FOR EACH ROW EXECUTE FUNCTION ledger_accounts_open_balance();--> statement-breakpoint
REVOKE ALL ON FUNCTION ledger_accounts_open_balance() FROM PUBLIC, buddha_app;--> statement-breakpoint
REVOKE INSERT, UPDATE, DELETE ON TABLE "balances" FROM buddha_app;--> statement-breakpoint
GRANT UPDATE ("available_coin", "locked_coin", "ledger_coin", "updated_at") ON TABLE "balances"
  TO buddha_app;--> statement-breakpoint
-- Hand-edited: a balance's total moves only with the ledger's (#116 수용 기준; PLAN 5.6). Each row
-- carries `ledger_coin`, the account's total as its ledger says, and every event moves it with the
-- bucket that pays or takes (`recordLedgerEntry`). Whoever writes, no UPDATE changes the gap
-- between the two — (available + locked) − ledger_coin — so a total never changes alone, and an
-- order's lock (#118: available ↔ locked of one account, no event, ADR-0107 결정 2 #73 1항) passes.
-- The gap is 0 unless an owner-level write with the triggers off or a dump restored without them
-- made one; such an account keeps its gap, unchanged, and still takes its events — payouts, grants,
-- fills, locks — as 10항 wants (an account mismatch refuses its new orders only, #93). Closing a gap
-- is #93's 대사 정정, which changes it under its own guarded exception, not here. Not deferred: a
-- writer moves both in one UPDATE. Only the gap: a `ledger_coin` that itself left the ledger's
-- total (the same owner-level writes) takes no event at all, a payout included — the event
-- continues the chain at INSERT and `ledger_coin` must say the chain's total at COMMIT — until the
-- owner resets the copy (docs/OPERATIONS.md '사본이 어긋났을 때', ADR-0109 12-8).
CREATE FUNCTION balances_keep_ledger_gap() RETURNS trigger
LANGUAGE plpgsql AS $$
BEGIN
  IF (NEW.available_coin + NEW.locked_coin) - NEW.ledger_coin
     IS DISTINCT FROM (OLD.available_coin + OLD.locked_coin) - OLD.ledger_coin THEN
    RAISE EXCEPTION 'ledger account % moves its total apart from its ledger''s (% Coin, ledger %)',
      NEW.account_id, NEW.available_coin + NEW.locked_coin, NEW.ledger_coin
      USING ERRCODE = 'integrity_constraint_violation', CONSTRAINT = TG_NAME;
  END IF;
  RETURN NEW;
END;
$$;--> statement-breakpoint
CREATE TRIGGER balances_keep_ledger_gap
  BEFORE UPDATE ON "balances"
  FOR EACH ROW EXECUTE FUNCTION balances_keep_ledger_gap();--> statement-breakpoint
-- Hand-edited: no ledger total changes without its event, and no event without its change (#116
-- 수용 기준): at COMMIT each ledger account a transaction touched carries in `ledger_coin` the
-- total its latest event says (`ledger_account_last_after`). With the gap kept above, a balance
-- changes only with its event too. Deferred, so a writer may update the row and insert the event in
-- either order. On `balances` only when `ledger_coin` changed: a lock moves neither. The row is
-- read again at COMMIT, its last state. Never the balance's own total: an account whose total
-- already left its ledger would then take no event at all, a payout included (10항). Equality,
-- not an offset kept: the offset before the transaction is not there to read at COMMIT, so a
-- `ledger_coin` copy that left its ledger blocks the account's events (the gap check above).
CREATE FUNCTION ledger_balances_agree() RETURNS trigger
LANGUAGE plpgsql SET search_path = pg_catalog, public, pg_temp AS $$
DECLARE
  accounts bigint[];
  account bigint;
  carried bigint;
BEGIN
  IF TG_TABLE_NAME = 'balances' THEN
    accounts := ARRAY[NEW.account_id];
  ELSE
    accounts := array_remove(ARRAY[NEW.from_account_id, NEW.to_account_id], NULL);
  END IF;
  FOREACH account IN ARRAY accounts LOOP
    SELECT b.ledger_coin INTO carried FROM balances b WHERE b.account_id = account;
    IF carried IS DISTINCT FROM ledger_account_last_after(account) THEN
      RAISE EXCEPTION 'ledger account % carries % Coin as its ledger total, but its ledger says %',
        account, carried, ledger_account_last_after(account)
        USING ERRCODE = 'integrity_constraint_violation', CONSTRAINT = TG_NAME;
    END IF;
  END LOOP;
  RETURN NULL;
END;
$$;--> statement-breakpoint
CREATE CONSTRAINT TRIGGER balances_follow_ledger
  AFTER UPDATE ON "balances"
  DEFERRABLE INITIALLY DEFERRED
  FOR EACH ROW
  WHEN (OLD.ledger_coin IS DISTINCT FROM NEW.ledger_coin)
  EXECUTE FUNCTION ledger_balances_agree();--> statement-breakpoint
CREATE CONSTRAINT TRIGGER ledger_entries_follow_balances
  AFTER INSERT ON "ledger_entries"
  DEFERRABLE INITIALLY DEFERRED
  FOR EACH ROW EXECUTE FUNCTION ledger_balances_agree();--> statement-breakpoint
-- Hand-edited: 0043's rule on the new shape (#140; ADR-0107 결정 5 #126 행): a forfeiture is the
-- closing account's own burn of its whole balance — CLOSURE_FORFEIT exactly when it refers to the
-- account itself (ref `account_closure`), from that person's user ledger account, to none, leaving
-- its total at 0 — and nothing is written to or from a closed account's user ledger account after
-- its closure: no fill, no settlement payout, no grant. Deferred, as before.
CREATE OR REPLACE FUNCTION ledger_entries_closed_account() RETURNS trigger
LANGUAGE plpgsql SET search_path = pg_catalog, public, pg_temp AS $$
DECLARE
  from_owner text;
  from_closed timestamptz;
  to_owner text;
  to_closed timestamptz;
BEGIN
  SELECT a.owner_id, p.closed_at INTO from_owner, from_closed
    FROM ledger_accounts a LEFT JOIN profiles p ON p.user_id = a.owner_id
   WHERE a.id = NEW.from_account_id AND a.kind = 'user';
  SELECT a.owner_id, p.closed_at INTO to_owner, to_closed
    FROM ledger_accounts a LEFT JOIN profiles p ON p.user_id = a.owner_id
   WHERE a.id = NEW.to_account_id AND a.kind = 'user';
  IF NEW.type::text = 'CLOSURE_FORFEIT' OR NEW.ref_type = 'account_closure' THEN
    IF NOT coalesce(NEW.type::text = 'CLOSURE_FORFEIT' AND NEW.ref_type = 'account_closure'
                    AND NEW.ref_id = from_owner AND NEW.to_account_id IS NULL
                    AND NEW.from_balance_after_coin = 0 AND from_closed IS NOT NULL, false) THEN
      RAISE EXCEPTION 'ledger entry % is a forfeiture only as the closing account''s own, of its whole balance',
        NEW.id
        USING ERRCODE = 'integrity_constraint_violation';
    END IF;
  ELSIF from_closed IS NOT NULL OR to_closed IS NOT NULL THEN
    RAISE EXCEPTION 'account % was closed at %: its ledger takes no entry after the closure',
      CASE WHEN from_closed IS NOT NULL THEN from_owner ELSE to_owner END,
      coalesce(from_closed, to_closed)
      USING ERRCODE = 'integrity_constraint_violation';
  END IF;
  RETURN NULL;
END;
$$;--> statement-breakpoint
-- Hand-edited: 0043's closure check with the ledger's total (#140, ADR-0086): a closed account
-- ends at 0 on both sides of its balance row — its buckets and its ledger's total. An account whose
-- total left its ledger (the gap above) therefore cannot close until #93's 대사 정정 closes the gap:
-- a forfeiture of its buckets would leave its ledger off 0, or one of its ledger its buckets. The
-- rest of the body is 0043's.
CREATE OR REPLACE FUNCTION profiles_closed_completely() RETURNS trigger
LANGUAGE plpgsql SET search_path = pg_catalog, public, pg_temp AS $$
DECLARE
  kept text;
BEGIN
  SELECT CASE
    WHEN EXISTS (SELECT FROM "session" WHERE "user_id" = NEW.user_id) THEN 'a session'
    WHEN EXISTS (SELECT FROM "account" WHERE "user_id" = NEW.user_id) THEN 'a sign-in method'
    WHEN EXISTS (SELECT FROM "verification"
                  WHERE "identifier" LIKE 'reset-password:%' AND "value" = NEW.user_id)
      THEN 'a password reset'
    WHEN EXISTS (SELECT FROM "phone_verifications" WHERE "user_id" = NEW.user_id)
      THEN 'its verified number'
    WHEN EXISTS (SELECT FROM "market_watches" WHERE "user_id" = NEW.user_id) THEN 'its watchlist'
    WHEN EXISTS (SELECT FROM "market_searches" WHERE "user_id" = NEW.user_id)
      THEN 'its search history'
    WHEN EXISTS (SELECT FROM "profile_interest_categories" WHERE "user_id" = NEW.user_id)
      THEN 'its interest categories'
    WHEN EXISTS (SELECT FROM "nickname_holds" WHERE "user_id" = NEW.user_id)
      THEN 'a nickname hold of its own'
    WHEN NEW.time_zone IS NOT NULL THEN 'its time zone'
    WHEN EXISTS (SELECT FROM "market_watch_events" e
                  WHERE e."user_id" = NEW.user_id AND e."action" = 'watch'
                    AND NOT EXISTS (SELECT FROM "market_watch_events" l
                                     WHERE l."user_id" = e."user_id"
                                       AND l."market_id" = e."market_id" AND l."id" > e."id"))
      THEN 'a watch with no unwatch event'
    WHEN EXISTS (SELECT FROM "balances"
                  WHERE "user_id" = NEW.user_id
                    AND ("available_coin" <> 0 OR "locked_coin" <> 0 OR "ledger_coin" <> 0))
      THEN 'Coin'
    WHEN NOT EXISTS (SELECT FROM "user"
                      WHERE "id" = NEW.user_id
                        AND "email" = 'closed_' || NEW.user_id || '@noemail.buddha.local'
                        AND "name" = '' AND "image" IS NULL)
      THEN 'its address, name or photo'
    WHEN EXISTS (SELECT FROM "approval_requests" r
                  WHERE r."status" = 'pending'
                    AND ((r."kind" = 'account_restriction' AND r."target_type" = 'user'
                          AND r."target_id" = NEW.user_id)
                      OR (r."kind" IN ('account_restriction_shorten', 'account_restriction_lift',
                                       'account_restriction_cancel')
                          AND r."target_type" = 'moderation_action'
                          AND EXISTS (SELECT FROM "moderation_actions" a
                                       WHERE a."id"::text = r."target_id"
                                         AND a."user_id" = NEW.user_id))))
      THEN 'a request about it waiting'
  END INTO kept;
  IF kept IS NOT NULL THEN
    RAISE EXCEPTION 'account % was closed keeping %', NEW.user_id, kept
      USING ERRCODE = 'integrity_constraint_violation';
  END IF;
  RETURN NULL;
END;
$$;--> statement-breakpoint
-- Hand-edited: 0031's rule on the new shape — a paid grant is paid only by its own START_GRANT, a
-- mint into its account's user ledger account of the same amount, referring to the grant.
CREATE OR REPLACE FUNCTION start_grants_keep_record() RETURNS trigger
LANGUAGE plpgsql SET search_path = pg_catalog, public, pg_temp AS $$
BEGIN
  IF NEW.id <> OLD.id OR NEW.user_id <> OLD.user_id OR NEW.created_at <> OLD.created_at THEN
    RAISE EXCEPTION 'start grant %: its account and recording time never change', OLD.id
      USING ERRCODE = 'integrity_constraint_violation';
  END IF;
  IF OLD.granted_at IS NOT NULL THEN
    RAISE EXCEPTION 'start grant % was paid at %: a paid grant never changes', OLD.id,
      OLD.granted_at
      USING ERRCODE = 'integrity_constraint_violation';
  END IF;
  IF OLD.cancelled_at IS NOT NULL THEN
    RAISE EXCEPTION 'start grant % was cancelled at %: a cancelled grant never changes', OLD.id,
      OLD.cancelled_at
      USING ERRCODE = 'integrity_constraint_violation';
  END IF;
  IF NEW.granted_at IS NOT NULL AND NOT EXISTS (
    SELECT 1 FROM ledger_entries e JOIN ledger_accounts a ON a.id = e.to_account_id
    WHERE e.id = NEW.ledger_entry_id
      AND e.from_account_id IS NULL
      AND a.kind = 'user'
      AND a.owner_id = NEW.user_id
      AND e.type = 'START_GRANT'
      AND e.amount_coin = NEW.amount_coin
      AND e.ref_type = 'start_grant'
      AND e.ref_id = NEW.id::text
  ) THEN
    RAISE EXCEPTION 'start grant % is paid only by its own START_GRANT ledger entry', OLD.id
      USING ERRCODE = 'integrity_constraint_violation';
  END IF;
  RETURN NEW;
END;
$$;--> statement-breakpoint
-- Hand-edited: 0059's body with the balance replaced by the ledger account (#116): a person's
-- account — a member, an admin — is made with its profile and its user ledger account, whose
-- `balances` row the trigger above opens at 0, no grant (ADR-0019, ADR-0071). The 운영 마켓메이커
-- gets neither a profile nor a ledger account of its own: its Coin is in each market's 마켓메이커
-- 자금 (ADR-0107 결정 2 #73 11항), and the ledger audit reads ledger accounts, not accounts.
CREATE OR REPLACE FUNCTION create_profile_for_user() RETURNS trigger
LANGUAGE plpgsql SET search_path = pg_catalog, public, pg_temp AS $$
DECLARE
  -- 32 unambiguous upper-case letters and digits (no 0/O/1/I): 32^4 = 1,048,576 suffixes.
  alphabet CONSTANT text := '23456789ABCDEFGHJKLMNPQRSTUVWXYZ';
  candidate text;
  i integer;
  attempt integer := 0;
BEGIN
  IF NOT is_human_account_type(NEW.account_type) THEN
    RETURN NEW;
  END IF;
  LOOP
    attempt := attempt + 1;
    candidate := 'user_';
    FOR i IN 1..4 LOOP
      candidate := candidate || substr(alphabet, 1 + floor(random() * 32)::integer, 1);
    END LOOP;
    PERFORM lock_nickname(candidate);
    IF NOT nickname_held(candidate, NEW.id) THEN
      BEGIN
        INSERT INTO profiles (user_id, nickname) VALUES (NEW.id, candidate);
        EXIT;
      EXCEPTION WHEN unique_violation THEN
        IF attempt >= 10 THEN RAISE; END IF;
      END;
    END IF;
    IF attempt >= 10 THEN
      RAISE EXCEPTION 'no free auto nickname for % after % candidates', NEW.id, attempt
        USING ERRCODE = 'unique_violation';
    END IF;
  END LOOP;
  INSERT INTO ledger_accounts (kind, owner_id) VALUES ('user', NEW.id);
  RETURN NEW;
END;
$$;
